<?php declare(strict_types=1); /** @var Closure(mixed):string $escape */ $money=static fn(float$v):string=>'R$ '.number_format($v,2,',','.');$statusNames=['PENDING'=>'Pendente','OVERDUE'=>'Vencida','RECEIVED'=>'Recebida','CONFIRMED'=>'Confirmada','RECEIVED_IN_CASH'=>'Recebida em dinheiro','CANCELED'=>'Cancelada'];$billingNames=['PIX'=>'PIX','BOLETO'=>'Boleto','CREDIT_CARD'=>'Cartão','UNDEFINED'=>'A definir'];$query=static function(array$changes)use($search,$statusFilter,$billingFilter,$startDate,$endDate):string{return http_build_query(array_filter(array_merge(['q'=>$search,'status'=>$statusFilter,'billing'=>$billingFilter,'start'=>$startDate,'end'=>$endDate],$changes),static fn($v):bool=>$v!==''));};$first=$result['total']===0?0:(($result['page']-1)*50)+1;$last=min($result['total'],$result['page']*50); ?>
<nav class="finance-section-tabs"><a class="active" href="<?= $escape($basePath) ?>/finance/payments">Cobranças</a><a href="<?= $escape($basePath) ?>/finance/subscriptions">Assinaturas</a></nav>
<div class="finance-customer-heading"><div><span class="status">Financeiro</span><h1>Cobranças</h1><p class="meta">Acompanhe recebimentos e vencimentos das unidades permitidas.</p></div><div class="finance-customer-total"><i class="fa-solid fa-file-invoice-dollar"></i><span><strong><?= number_format((int)$result['total'],0,',','.') ?></strong> cobranças encontradas</span></div></div>
<div class="dashboard-grid mb-4"><article class="metric-card"><span>Pendentes</span><strong><?= number_format((int)$result['summary']['pending'],0,',','.') ?></strong></article><article class="metric-card"><span>Vencidas</span><strong class="finance-open-value"><?= number_format((int)$result['summary']['overdue'],0,',','.') ?></strong></article><article class="metric-card"><span>Recebidas</span><strong><?= number_format((int)$result['summary']['received'],0,',','.') ?></strong></article><article class="metric-card"><span>Valor em aberto</span><strong class="finance-open-value"><?= $escape($money((float)$result['summary']['open_value'])) ?></strong></article></div>
<section class="finance-customer-toolbar"><form method="get" action="<?= $escape($basePath) ?>/finance/payments"><div class="finance-search-row"><label class="finance-search-box"><i class="fa-solid fa-magnifying-glass"></i><input name="q" value="<?= $escape($search) ?>" placeholder="Aluno, CPF/CNPJ, descrição ou ID da cobrança"></label><button class="button-primary finance-search-button" type="submit">Pesquisar</button><details class="finance-filter-panel"<?= ($statusFilter!==''||$billingFilter!==''||$startDate!==''||$endDate!=='')?' open':'' ?>><summary><i class="fa-solid fa-filter"></i> Filtros</summary><div class="finance-filter-content"><label>Situação<select name="status"><option value="">Todas</option><?php foreach(['PENDING'=>'Pendente','OVERDUE'=>'Vencida','RECEIVED'=>'Recebida','CONFIRMED'=>'Confirmada','CANCELED'=>'Cancelada']as$value=>$label):?><option value="<?= $value ?>"<?= $statusFilter===$value?' selected':'' ?>><?= $label ?></option><?php endforeach;?></select></label><label>Forma<select name="billing"><option value="">Todas</option><option value="PIX"<?= $billingFilter==='PIX'?' selected':'' ?>>PIX</option><option value="BOLETO"<?= $billingFilter==='BOLETO'?' selected':'' ?>>Boleto</option><option value="CREDIT_CARD"<?= $billingFilter==='CREDIT_CARD'?' selected':'' ?>>Cartão</option></select></label><label>Vencimento inicial<input name="start" type="date" value="<?= $escape($startDate) ?>"></label><label>Vencimento final<input name="end" type="date" value="<?= $escape($endDate) ?>"></label><div class="finance-filter-actions"><button class="button-primary" type="submit">Aplicar</button><a class="button-secondary" href="<?= $escape($basePath) ?>/finance/payments">Limpar</a></div></div></details></div></form></section>
<div class="finance-result-bar"><span>Exibindo <strong><?= $first ?>–<?= $last ?></strong> de <?= number_format((int)$result['total'],0,',','.') ?></span><span><i class="fa-solid fa-shield-halved"></i> Dados conforme suas permissões</span></div>
<div class="table-responsive finance-customer-table"><table><thead><tr><th>Vencimento</th><th>Cliente</th><th>Descrição</th><th>Unidade</th><th>Forma</th><th>Valor</th><th>Situação</th><th>Ações</th></tr></thead><tbody><?php if($result['items']===[]):?><tr><td colspan="8"><div class="finance-empty"><i class="fa-solid fa-file-circle-xmark"></i><strong>Nenhuma cobrança encontrada</strong></div></td></tr><?php endif;?><?php foreach($result['items']as$item):?><tr><td><?= $escape($item['due_date']?date('d/m/Y',strtotime($item['due_date'])):'—') ?></td><td><?php if($item['finance_customer_id']):?><a href="<?= $escape($basePath) ?>/finance/customers/<?= (int)$item['finance_customer_id'] ?>"><strong><?= $escape($item['customer_name']?:'Cliente sem nome') ?></strong></a><?php else:?><span>Cliente legado</span><?php endif;?></td><td><?= $escape($item['description']?:'Cobrança Asaas') ?></td><td><?= $escape($item['unit_name']?:'Sem unidade') ?></td><td><?= $escape($billingNames[$item['billing_type']]??$item['billing_type']??'—') ?></td><td><strong><?= $escape($money((float)$item['value'])) ?></strong></td><td><span class="connection-badge"><?= $escape($statusNames[$item['status']]??$item['status']) ?></span></td><td><?php if($item['invoice_url']):?><a href="<?= $escape($item['invoice_url']) ?>" target="_blank" rel="noopener">Fatura</a><?php endif;?><?php if($item['finance_customer_id']&&in_array($item['status'],['PENDING','OVERDUE'],true)):?> <a href="<?= $escape($basePath) ?>/finance/customers/<?= (int)$item['finance_customer_id'] ?>/payments/<?= (int)$item['id'] ?>/edit">Editar</a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div>
<?php if($result['pages']>1):?><nav class="finance-pagination"><span>Página <?= (int)$result['page'] ?> de <?= (int)$result['pages'] ?></span><div><?php if($result['page']>1):?><a href="?<?= $escape($query(['page'=>$result['page']-1])) ?>"><i class="fa-solid fa-chevron-left"></i></a><?php endif;?><span><?= (int)$result['page'] ?></span><?php if($result['page']<$result['pages']):?><a href="?<?= $escape($query(['page'=>$result['page']+1])) ?>"><i class="fa-solid fa-chevron-right"></i></a><?php endif;?></div></nav><?php endif;?>
